<?php
require_once dirname(__DIR__).'/includes/features.php';admin_require();$errors=[];
$tables=['contact'=>'contact_requests','demo'=>'demo_requests','consultation'=>'consultation_bookings'];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{admin_csrf();
  if(($_POST['action']??'')==='logout'){unset($_SESSION['admin_until']);session_regenerate_id(true);redirect('admin/login.php');}
  $type=input_text($_POST,'type',20);$id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
  if(!isset($tables[$type])||!$id)throw new InvalidArgumentException('Invalid enquiry reference.');
  $find=db()->prepare('SELECT id FROM '.$tables[$type].' WHERE id=?');$find->execute([$id]);if(!$find->fetchColumn())throw new InvalidArgumentException('Enquiry not found.');
  if(($_POST['action']??'')==='status'&&$type!=='consultation'){
   $status=input_text($_POST,'status',20);if(!in_array($status,['new','contacted','closed'],true))throw new InvalidArgumentException('Invalid status.');
   db()->prepare('UPDATE '.$tables[$type].' SET status=? WHERE id=?')->execute([$status,$id]);
  }elseif(($_POST['action']??'')==='note'){
   $note=input_text($_POST,'note',4000);if($note==='')throw new InvalidArgumentException('Write a note before saving.');
   db()->prepare('INSERT INTO enquiry_notes (request_type,request_id,note) VALUES (?,?,?)')->execute([$type,$id,$note]);
  }else throw new InvalidArgumentException('Invalid action.');
  redirect('admin/inbox.php?'.http_build_query(['type'=>$type,'id'=>$id]));
 }catch(Throwable $e){$errors['_form']=$e instanceof InvalidArgumentException?$e->getMessage():'The update could not be saved. Check database configuration and migration.';}
}
$type=is_string($_GET['type']??null)&&isset($tables[$_GET['type']])?$_GET['type']:'';
$status=is_string($_GET['status']??null)&&in_array($_GET['status'],['new','contacted','closed','confirmed','cancelled'],true)?$_GET['status']:'';
$selectedId=filter_var($_GET['id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$page=max(1,min(100000,(int)($_GET['page']??1)));$offset=($page-1)*30;
$rows=[];$selected=null;$notes=[];$brief=[];
try{
 $union="SELECT 'contact' AS kind,id,name,email,subject AS topic,status,internal_email_status,created_at FROM contact_requests UNION ALL SELECT 'demo',id,name,email,service_slug,status,internal_email_status,created_at FROM demo_requests UNION ALL SELECT 'consultation',id,name,email,'Consultation',status,internal_email_status,created_at FROM consultation_bookings";
 $where=[];$params=[];if($type){$where[]='kind=?';$params[]=$type;}if($status){$where[]='status=?';$params[]=$status;}
 $q=db()->prepare('SELECT * FROM ('.$union.') enquiries'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC,id DESC LIMIT 31 OFFSET '.$offset);$q->execute($params);$rows=$q->fetchAll();$hasNext=count($rows)>30;$rows=array_slice($rows,0,30);
 if($type&&$selectedId){
  $q=db()->prepare('SELECT * FROM '.$tables[$type].' WHERE id=?');$q->execute([$selectedId]);$selected=$q->fetch();
  if($selected){$q=db()->prepare('SELECT note,created_at FROM enquiry_notes WHERE request_type=? AND request_id=? ORDER BY id DESC');$q->execute([$type,$selectedId]);$notes=$q->fetchAll();
   if($type==='contact'){$q=db()->prepare('SELECT brief_json FROM enquiry_briefs WHERE contact_id=?');$q->execute([$selectedId]);$brief=json_decode($q->fetchColumn()?:'{}',true)?:[];}
  }
 }
}catch(Throwable $e){$hasNext=false;$errors['_form']='Inbox storage is unavailable. Import database/features.sql and configure the database.';}
page_start('admin',''); ?>
<section class="section"><div class="container"><h1>Enquiry inbox</h1><?php admin_navigation();errors_summary($errors); ?><form class="admin-bar" method="get"><label>Request type<select name="type"><option value="">All requests</option><?php foreach($tables as $kind=>$unused): ?><option value="<?= e($kind) ?>" <?= $kind===$type?'selected':'' ?>><?= e(ucfirst($kind)) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['new','contacted','closed','confirmed','cancelled'] as $option): ?><option <?= $option===$status?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="button button-small">Filter</button></form>
<?php if($selected): ?><article class="form-card inbox-detail"><p class="eyebrow"><?= e($type==='consultation'?'CONSULT':strtoupper($type)) ?>-<?= (int)$selected['id'] ?></p><h2><?= e($selected['name']) ?></h2><a class="text-link" href="mailto:<?= e($selected['email']) ?>"><?= e($selected['email']) ?></a><p><?= e($selected['phone']) ?></p><?php if($type==='demo'): ?><p><?= e(data('demo_services')[$selected['service_slug']]['name']??$selected['service_slug']) ?> · Requested: <?= e($selected['preferred_date'].' '.$selected['preferred_time'].' '.$selected['timezone']) ?></p><p>Visitor email: <?= e($selected['confirmation_email_status']) ?></p><?php $answers=json_decode($selected['extra_data'],true)?:[];foreach(data('demo_services')[$selected['service_slug']]['extra_fields']??[] as $field): ?><p><strong><?= e($field['label']) ?>:</strong> <?= e(is_array($answers[$field['name']]??'')?implode(', ',$answers[$field['name']]):($answers[$field['name']]??'')) ?></p><?php endforeach; ?><?php elseif($type==='contact'): ?><p><strong><?= e($selected['subject']) ?></strong></p><?php elseif($type==='consultation'): ?><p>Visitor email: <?= e($selected['confirmation_email_status']) ?></p><a class="text-link" href="<?= e(url('admin/calendar.php')) ?>">View booking in calendar</a><?php endif; ?><p class="preserved-text"><?= nl2br(e($selected['message'])) ?></p><?php if($brief): ?><h3>Project brief</h3><dl class="summary-list"><?php foreach($brief as $label=>$value): ?><dt><?= e(ucfirst($label)) ?></dt><dd><?= e($value) ?></dd><?php endforeach; ?></dl><?php endif; ?><p class="note">Internal email: <?= e($selected['internal_email_status']) ?> · Received <?= e($selected['created_at']) ?> UTC</p>
<?php if($type!=='consultation'): ?><form method="post" class="admin-bar"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="type" value="<?= e($type) ?>"><input type="hidden" name="id" value="<?= (int)$selectedId ?>"><label>Status<select name="status"><?php foreach(['new','contacted','closed'] as $option): ?><option <?= $option===$selected['status']?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="button button-small">Update status</button></form><?php endif; ?>
<h3>Internal notes</h3><?php foreach($notes as $note): ?><div class="inbox-note"><p><?= nl2br(e($note['note'])) ?></p><small><?= e($note['created_at']) ?> UTC</small></div><?php endforeach; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="note"><input type="hidden" name="type" value="<?= e($type) ?>"><input type="hidden" name="id" value="<?= (int)$selectedId ?>"><?php field('note','Add an internal note','textarea',[],[],true); ?><button class="button button-small">Save note</button><p class="note">Notes stay in admin. They are not emailed to the visitor.</p></form></article><?php endif; ?>
<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Contact</th><th>Request</th><th>Status</th><th>Internal email</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a class="text-link" href="<?= e(url('admin/inbox.php').'?'.http_build_query(['type'=>$row['kind'],'id'=>$row['id']])) ?>"><?= e($row['kind']==='consultation'?'CONSULT':strtoupper($row['kind'])) ?>-<?= (int)$row['id'] ?></a><br><?= e($row['created_at']) ?> UTC</td><td><?= e($row['name']) ?><br><?= e($row['email']) ?></td><td><?= e($row['kind']==='demo'?(data('demo_services')[$row['topic']]['name']??$row['topic']):$row['topic']) ?></td><td><?= e($row['status']) ?></td><td><?= e($row['internal_email_status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$rows&&!$errors): ?><p>No matching requests.</p><?php endif; ?><div class="actions"><?php if($page>1): ?><a class="button button-outline" href="<?= e(url('admin/inbox.php').'?'.http_build_query(['type'=>$type,'status'=>$status,'page'=>$page-1])) ?>">Previous</a><?php endif; ?><?php if($hasNext): ?><a class="button" href="<?= e(url('admin/inbox.php').'?'.http_build_query(['type'=>$type,'status'=>$status,'page'=>$page+1])) ?>">Next</a><?php endif; ?></div></div></section><?php page_end(); ?>
